import{_ as e,o as i,c as a,ae as l}from"./chunks/framework.2y7dWHft.js";const _=JSON.parse('{"title":"Vite 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"vite/what-is-vite.md","filePath":"vite/what-is-vite.md"}'),d={name:"vite/what-is-vite.md"};function r(o,t,h,s,n,c){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="vite-是什么" tabindex="-1">Vite 是什么 <a class="header-anchor" href="#vite-是什么" aria-label="Permalink to &quot;Vite 是什么&quot;">​</a></h1><p>Vite 是一个新一代的前端构建工具，由 Vue.js 的作者尤雨溪开发。</p><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><h3 id="_1-极速的服务启动" tabindex="-1">1. 极速的服务启动 <a class="header-anchor" href="#_1-极速的服务启动" aria-label="Permalink to &quot;1. 极速的服务启动&quot;">​</a></h3><ul><li>利用浏览器原生 ES 模块（ESM）能力，无需打包</li><li>按需编译，只编译当前请求的模块</li><li>冷启动速度比传统构建工具快 10-100 倍</li></ul><h3 id="_2-即时的热模块更新-hmr" tabindex="-1">2. 即时的热模块更新（HMR） <a class="header-anchor" href="#_2-即时的热模块更新-hmr" aria-label="Permalink to &quot;2. 即时的热模块更新（HMR）&quot;">​</a></h3><ul><li>无论应用大小，HMR 始终保持快速</li><li>保持应用状态的同时更新模块</li><li>性能不受模块数量影响</li></ul><h3 id="_3-丰富的功能特性" tabindex="-1">3. 丰富的功能特性 <a class="header-anchor" href="#_3-丰富的功能特性" aria-label="Permalink to &quot;3. 丰富的功能特性&quot;">​</a></h3><ul><li>TypeScript / JSX 支持</li><li>CSS 预处理器支持（Sass、Less、Stylus）</li><li>CSS Modules</li><li>PostCSS</li><li>支持 Web Components</li><li>图片和字体资源处理</li></ul><h2 id="与传统构建工具对比" tabindex="-1">与传统构建工具对比 <a class="header-anchor" href="#与传统构建工具对比" aria-label="Permalink to &quot;与传统构建工具对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>Vite</th><th>Webpack</th></tr></thead><tbody><tr><td>开发启动速度</td><td>极快（秒级）</td><td>较慢（分钟级）</td></tr><tr><td>热更新速度</td><td>毫秒级</td><td>秒级</td></tr><tr><td>配置复杂度</td><td>简单</td><td>复杂</td></tr><tr><td>生产构建</td><td>使用 Rollup</td><td>自身</td></tr><tr><td>生态成熟度</td><td>快速成长</td><td>非常成熟</td></tr></tbody></table><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>✅ Vue/React 项目开发</li><li>✅ 需要快速原型开发</li><li>✅ 追求极致的开发体验</li><li>✅ 中小型项目构建</li><li>⚠️ 超大型项目可能需要更多配置优化</li></ul><h2 id="生态系统" tabindex="-1">生态系统 <a class="header-anchor" href="#生态系统" aria-label="Permalink to &quot;生态系统&quot;">​</a></h2><p>Vite 拥有丰富的插件生态，可以通过插件扩展功能：</p><ul><li><code>@vitejs/plugin-vue</code> - Vue 3 支持</li><li><code>@vitejs/plugin-react</code> - React 支持</li><li><code>vite-plugin-svgr</code> - SVG 组件化</li><li><code>vite-plugin-windicss</code> - Windi CSS 支持</li><li>等等...</li></ul>',16)])])}const p=e(d,[["render",r]]);export{_ as __pageData,p as default};
